const available=()=>motes.filter(m=>m.got).length-people.reduce((n,p)=>n+p.stage,0);
const totalGot=()=>motes.filter(m=>m.got).length;
function nearest(){let found=null,d=999;for(const p of people){let n=Math.hypot(p.x-player.x,p.y-player.y);if(n<53&&n<d){found=p;d=n}}return found}
function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function refresh(){const list=document.getElementById('villagerList');list.innerHTML='';for(const p of people){const row=document.createElement('div');row.className='villager';row.innerHTML=`<div class="avatar">${p.stage===3?p.icon:['🧑','✨','🌱'][p.stage]}</div><div class="v-info"><div class="v-name">${p.name} <span style="font-weight:500;color:#89958a">· ${p.role}</span></div><div class="v-state">${p.stage===3?'CAUGHT':p.stage===0?'WAITING':`${p.stage}/3 · ${p.stage===1?'SPARKING':p.stage===2?'CHANGING':'READY'}`}</div></div><div class="v-stage">${[1,2,3].map(i=>`<i class="pip ${p.stage>=i?'on':''}"></i>`).join('')}</div>`;row.addEventListener('click',()=>{active=p;const n=Math.hypot(p.x-player.x,p.y-player.y);if(n<60)openDialogue(p);else showToast(`Find ${p.name} near the ${p.role.toLowerCase()}'s place.`)});list.appendChild(row)}
const caught=people.filter(p=>p.stage===3).length;document.getElementById('moteCount').textContent=`✦ ${totalGot()} / 12`;document.getElementById('questProgress').style.width=`${Math.max(3,totalGot()/12*100)}%`;document.getElementById('collectionCount').textContent=`${caught} caught`;
const quest=document.getElementById('questText');if(gameWon)quest.textContent='Every neighbor has found their wild little self. Mossbell is glowing brighter than ever!';else if(totalGot()<12)quest.textContent=`Look for the floating golden wisps. ${12-totalGot()} ${12-totalGot()===1?'wisp':'wisps'} still sparkle around the village.`;else quest.textContent=`The village is full of magic. ${caught<4?`Help your neighbors transform and catch them (${caught}/4).`:'Every neighbor is ready for their new adventure!'}`;
const col=document.getElementById('collection');if(!caught)col.className='collection-empty',col.textContent='Your journal is waiting for its first little friend.';else{col.className='collection-grid';col.innerHTML=people.filter(p=>p.stage===3).map(p=>`<div class="creature" title="${p.final} — ${p.species}">${p.icon}</div>`).join('')}
document.getElementById('sceneStatus').textContent=gameWon?'A village full of wonder':'A quiet morning';}
function openDialogue(p){active=p;dialogOpen=true;document.getElementById('dialogue').classList.add('open');renderDialogue()}
function closeDialogue(){dialogOpen=false;document.getElementById('dialogue').classList.remove('open')}
function renderDialogue(message){if(!active)return;const p=active;document.getElementById('speaker').textContent=`${p.name} · ${p.role}`;let textEl=document.getElementById('dialogText'),actions=document.getElementById('dialogActions');actions.innerHTML='';const btn=(label,fn,primary=false,disabled=false)=>{let b=document.createElement('button');b.className=`action${primary?' primary':''}`;b.textContent=label;b.disabled=disabled;b.onclick=fn;actions.appendChild(b)};
if(message){textEl.textContent=message;btn('Lovely ✦',closeDialogue,true);return}
if(p.stage===0){textEl.textContent=p.quote;btn('Tell me more',()=>renderDialogue(`${p.name} smiles nervously. “${p.species} I think... but it feels like a story I haven't finished yet.”`));btn('Share a wisp ✦',()=>advance(p),true,available()<1)}
else if(p.stage<3){const lines=['A warm little spark is fluttering in my chest.','My old shape is getting softer around the edges...','I can feel my true self, just one more step!'];textEl.textContent=lines[p.stage-1]+` ${p.stage<2?'Would you share another wisp?':'One last bit of magic, please!'}`;btn('Share a wisp ✦',()=>advance(p),true,available()<1)}
else{textEl.textContent=`${p.final} is ready to join your Lantern Journal! ${p.species}`;btn('Capture with a lantern ✦',()=>capture(p),true);}}
function advance(p){if(available()<1){renderDialogue('No loose wisps yet. Wander through the village and look for the floating golden ✦ sparks.');return}p.stage++;for(let i=0;i<16;i++)particles.push({x:p.x+(Math.random()-.5)*38,y:p.y+(Math.random()-.5)*28,life:35,color:['#fff0a0',p.creature,'#ffffff'][i%3]});refresh();const texts=[`A golden wisp drifts into ${p.name}'s heart. A tiny crest of color appears—something is beginning!`,`The magic blooms! ${p.name} sprouts new ears, feathers, fins, or wings. Their creature shape is shining through!`,`The last wisp swirls around ${p.name}. Their transformation is complete—they're ready to be caught!`];renderDialogue(texts[p.stage-1])}
function capture(p){p.stage=3;gameWon=people.every(q=>q.stage===3);refresh();for(let i=0;i<28;i++)particles.push({x:p.x+(Math.random()-.5)*60,y:p.y+(Math.random()-.5)*55,life:42,color:['#fff0a0',p.creature,'#f5d477'][i%3]});if(gameWon){document.getElementById('speaker').textContent='A whole village of wonder!';document.getElementById('dialogText').textContent='You did it! All four neighbors found their true forms and joined your Lantern Journal. The little village glows with shared magic. Your story can keep going—wander, revisit your friends, and enjoy Mossbell!';document.getElementById('dialogActions').innerHTML='';let b=document.createElement('button');b.className='action primary';b.textContent='Keep exploring';b.onclick=closeDialogue;document.getElementById('dialogActions').appendChild(b)}else renderDialogue(`${p.name} is safe and sound in your Lantern Journal! Their new adventure begins.`)}
function interact(){if(dialogOpen){closeDialogue();return}const p=nearest();if(p){openDialogue(p);return}let nearestM=motes.find(m=>!m.got&&Math.hypot(m.x-player.x,m.y-player.y)<34);if(nearestM){nearestM.got=true;particles.push({x:nearestM.x,y:nearestM.y,life:30,color:'#fff0a0'});refresh();showToast(`A village wisp joins your bag! ✦ ${available()} ready`);return}showToast('No one nearby—wander toward a neighbor or a golden wisp!')}
function move(dt){if(dialogOpen)return;let dx=0,dy=0;if(keys.has('ArrowLeft')||keys.has('a')||keys.has('A'))dx--;if(keys.has('ArrowRight')||keys.has('d')||keys.has('D'))dx++;if(keys.has('ArrowUp')||keys.has('w')||keys.has('W'))dy--;if(keys.has('ArrowDown')||keys.has('s')||keys.has('S'))dy++;if(dx||dy){let len=Math.hypot(dx,dy);player.x+=dx/len*135*dt;player.y+=dy/len*135*dt;player.dir=dx?dx>0?'right':'left':dy>0?'down':'up';player.walk+=dt*13;player.x=Math.max(15,Math.min(W-15,player.x));player.y=Math.max(25,Math.min(H-16,player.y));}for(const m of motes){if(!m.got&&Math.hypot(m.x-player.x,m.y-player.y)<18){m.got=true;for(let i=0;i<7;i++)particles.push({x:m.x+(Math.random()-.5)*18,y:m.y,life:22,color:'#fff0a0'});refresh();showToast(`Wisp found! ${totalGot()} / 12 ✦`)}}
const n=nearest(),prompt=document.getElementById('prompt');if(n&&!dialogOpen){prompt.style.display='block';prompt.style.left=`${n.x/W*100}%`;prompt.style.top=`${(n.y-24)/H*100}%`;prompt.textContent=n.stage===3?'E · SAY HI':'E · TALK'}else prompt.style.display='none'}
let prev=performance.now();function loop(now){let dt=Math.min(.04,(now-prev)/1000);prev=now;move(dt);requestAnimationFrame(loop)}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key);if((e.key==='e'||e.key==='E'||e.key===' ')&&!e.repeat)interact();if(e.key==='Escape')closeDialogue()});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());
document.getElementById('closeDialog').onclick=closeDialogue;document.getElementById('mobileInteract').onclick=interact;
document.querySelectorAll('.dpad button').forEach(b=>{const dir=b.dataset.dir,key={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[dir];b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(key);b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys.delete(key))});
document.getElementById('resetBtn').onclick=()=>{if(confirm('Start a fresh adventure? Your current journal will be cleared.'))location.reload()};
refresh();drawScene();requestAnimationFrame(loop);
})();
</script></body></html>

